export function createAuthenticationService({
  requestAuthentication,
  waitForActiveWork,
  deviceSession,
}) {
  return {
    async signIn(credentials) {
      const session = await requestAuthentication(credentials);
      // 실제 sync·cleanup·DB 조율기의 연결 위치다. 이 예시는 대기 경계만 실행한다.
      await waitForActiveWork();
      return deviceSession.applyAuthentication(session);
    },
  };
}

export function createSignInAndRequestRefresh({
  authenticationService,
  requestSessionRefresh,
  onRefreshError,
}) {
  return async function signInAndRequestRefresh(credentials, { onSignedIn }) {
    const session = await authenticationService.signIn(credentials);

    // 요청은 인증 뒤에 시작하되 재조회 결과는 인증 완료를 막지 않는다.
    // 두 callback은 오류를 다시 던지지 않는 소비자 계약을 갖는다.
    try {
      Promise.resolve(requestSessionRefresh()).catch(onRefreshError);
    } catch (error) {
      onRefreshError(error);
    }

    onSignedIn(session);
    return session;
  };
}

export function createLoginConsumer({
  signInAndRequestRefresh,
  showMessage,
  navigateToTrips,
}) {
  return function submitLogin(credentials) {
    return signInAndRequestRefresh(credentials, {
      onSignedIn() {
        showMessage("로그인 완료");
        navigateToTrips();
      },
    });
  };
}

export function createReauthConsumer({
  signInAndRequestRefresh,
  showMessage,
  closeDialog,
}) {
  return function submitReauthentication(credentials) {
    return signInAndRequestRefresh(credentials, {
      onSignedIn() {
        showMessage("인증을 복구했어요");
        closeDialog();
      },
    });
  };
}

import { setImmediate } from "node:timers/promises";
import { createDeviceSessionStore } from "./device-session.mjs";
import {
  createAuthenticationService,
  createSignInAndRequestRefresh,
} from "./authentication.mjs";
import { createLoginConsumer } from "./consumers.mjs";

let persistedSession = null;
let finishRefresh;
let failRefresh;
const refresh = new Promise((resolve, reject) => {
  finishRefresh = resolve;
  failRefresh = reject;
});

const deviceSession = createDeviceSessionStore({
  localData: { accountId: "demo-user", trips: ["기존 여행"] },
  async persistSession(session) {
    persistedSession = session;
    console.log("1. 기기 저장 완료(메모리 어댑터)");
  },
});

const authenticationService = createAuthenticationService({
  async requestAuthentication() {
    return { accountId: "demo-user", accessToken: "demo-token" };
  },
  async waitForActiveWork() {
    // 실제 제품의 sync·cleanup·DB 작업 대신 즉시 종료하는 예시 어댑터다.
  },
  deviceSession,
});

const signInAndRequestRefresh = createSignInAndRequestRefresh({
  authenticationService,
  requestSessionRefresh() {
    console.log(`2. 공개 상태 확인: ${deviceSession.readSnapshot().status}`);
    console.log("3. Query 갱신 요청(아직 진행 중)");
    return refresh;
  },
  onRefreshError(error) {
    console.log(`6. 조회 후속 실패 별도 처리: ${error.message}`);
  },
});

const submitLogin = createLoginConsumer({
  signInAndRequestRefresh,
  showMessage(message) {
    console.log(`4. 완료 안내: ${message}`);
  },
  navigateToTrips() {
    console.log("5. Login 소비자의 이동 요청(UI 없음)");
  },
});

await submitLogin({ email: "demo@example.test" });

if (process.argv.includes("--refresh-fails")) {
  failRefresh(new Error("예시 조회 오류"));
} else {
  finishRefresh();
  console.log("6. 인증 완료 전달 이후 Query 갱신 완료");
}

await setImmediate();
const snapshot = deviceSession.readSnapshot();
console.log(
  `최종 상태: ${snapshot.status}, 저장 계정: ${persistedSession.accountId}, 보존한 여행: ${snapshot.localData.trips.length}개`,
);

export class SessionOwnershipError extends Error {
  constructor() {
    super("기존 계정 또는 로컬 데이터의 귀속을 확인해야 합니다.");
    this.name = "SessionOwnershipError";
  }
}

export function createDeviceSessionStore({
  initialSession = null,
  localData = { accountId: null, trips: [] },
  persistSession,
}) {
  let session = structuredClone(initialSession);
  const retainedData = structuredClone(localData);

  return {
    readSnapshot() {
      return structuredClone({
        status: session ? "signed-in" : "signed-out",
        session,
        localData: retainedData,
      });
    },

    async applyAuthentication(nextSession) {
      const candidate = structuredClone(nextSession);
      const belongsToAnotherAccount =
        session && session.accountId !== candidate.accountId;
      const hasUnmatchedData =
        retainedData.trips.length > 0 &&
        retainedData.accountId !== candidate.accountId;

      if (belongsToAnotherAccount || hasUnmatchedData) {
        throw new SessionOwnershipError();
      }

      // 저장이 실패하면 공개 상태와 보존한 여행 데이터를 바꾸지 않는다.
      await persistSession(structuredClone(candidate));
      session = candidate;
      return structuredClone(session);
    },
  };
}

import test from "node:test";
import assert from "node:assert/strict";
import { setImmediate } from "node:timers/promises";
import {
  createDeviceSessionStore,
  SessionOwnershipError,
} from "../src/device-session.mjs";
import {
  createAuthenticationService,
  createSignInAndRequestRefresh,
} from "../src/authentication.mjs";
import {
  createLoginConsumer,
  createReauthConsumer,
} from "../src/consumers.mjs";

const oldSession = { accountId: "same-user", accessToken: "old-token" };
const newSession = { accountId: "same-user", accessToken: "new-token" };
const localData = { accountId: "same-user", trips: ["기존 여행"] };

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((done, fail) => {
    resolve = done;
    reject = fail;
  });
  return { promise, resolve, reject };
}

function setup(overrides = {}) {
  const events = [];
  const refreshErrors = [];
  let persistedSession = structuredClone(oldSession);
  const deviceSession = createDeviceSessionStore({
    initialSession: oldSession,
    localData,
    async persistSession(session) {
      events.push("persist:start");
      await overrides.persistSession?.(session);
      persistedSession = session;
      events.push("persist:done");
    },
  });
  const authenticationService = createAuthenticationService({
    async requestAuthentication() {
      events.push("authenticate");
      return overrides.requestAuthentication
        ? overrides.requestAuthentication()
        : newSession;
    },
    async waitForActiveWork() {
      events.push("active-work:wait");
      await overrides.waitForActiveWork?.();
      events.push("active-work:done");
    },
    deviceSession,
  });
  const signInAndRequestRefresh = createSignInAndRequestRefresh({
    authenticationService,
    requestSessionRefresh() {
      // Query를 시작할 때 공개 상태와 저장된 세션이 일치하는지 확인한다.
      assert.deepEqual(deviceSession.readSnapshot().session, newSession);
      assert.deepEqual(persistedSession, newSession);
      events.push("refresh:request");
      return overrides.requestSessionRefresh?.();
    },
    onRefreshError(error) {
      refreshErrors.push(error);
      events.push("refresh:error");
    },
  });

  return {
    events,
    refreshErrors,
    deviceSession,
    signInAndRequestRefresh,
    readPersistedSession: () => structuredClone(persistedSession),
    onSignedIn(session) {
      assert.deepEqual(session, newSession);
      events.push("signed-in");
    },
  };
}

test("진행 작업과 기기 저장이 끝난 뒤 상태를 적용하고 Query 요청·인증 완료를 전달한다", async () => {
  const activeWork = deferred();
  const persistence = deferred();
  const query = deferred();
  const run = setup({
    waitForActiveWork: () => activeWork.promise,
    persistSession: () => persistence.promise,
    requestSessionRefresh: () => query.promise,
  });

  const result = run.signInAndRequestRefresh({}, { onSignedIn: run.onSignedIn });
  await setImmediate();
  assert.deepEqual(run.events, ["authenticate", "active-work:wait"]);
  assert.deepEqual(run.deviceSession.readSnapshot().session, oldSession);

  activeWork.resolve();
  await setImmediate();
  assert.equal(run.events.at(-1), "persist:start");
  assert.deepEqual(run.deviceSession.readSnapshot().session, oldSession);
  assert.deepEqual(run.readPersistedSession(), oldSession);

  persistence.resolve();
  assert.deepEqual(await result, newSession);
  assert.deepEqual(run.events, [
    "authenticate",
    "active-work:wait",
    "active-work:done",
    "persist:start",
    "persist:done",
    "refresh:request",
    "signed-in",
  ]);
  assert.deepEqual(run.deviceSession.readSnapshot().localData, localData);
  // Query를 끝내기 전에도 로그인 호출이 이미 완료됐다.
  query.resolve();
});

test("기기 저장 실패는 이전 상태·데이터를 보존하고 Query와 완료 알림을 시작하지 않는다", async () => {
  const failure = new Error("기기 저장 실패");
  const run = setup({ persistSession: async () => { throw failure; } });

  await assert.rejects(
    run.signInAndRequestRefresh({}, { onSignedIn: run.onSignedIn }),
    (error) => error === failure,
  );

  assert.deepEqual(run.deviceSession.readSnapshot(), {
    status: "signed-in",
    session: oldSession,
    localData,
  });
  assert.deepEqual(run.readPersistedSession(), oldSession);
  assert.equal(run.events.includes("refresh:request"), false);
  assert.equal(run.events.includes("signed-in"), false);
  assert.deepEqual(run.refreshErrors, []);
});

test("후속 Query 실패는 인증 성공을 되돌리거나 인증 호출 실패로 바꾸지 않는다", async () => {
  const query = deferred();
  const failure = new Error("조회 실패");
  const run = setup({ requestSessionRefresh: () => query.promise });

  assert.deepEqual(
    await run.signInAndRequestRefresh({}, { onSignedIn: run.onSignedIn }),
    newSession,
  );
  query.reject(failure);
  await setImmediate();

  assert.deepEqual(run.refreshErrors, [failure]);
  assert.deepEqual(run.deviceSession.readSnapshot().session, newSession);
  assert.deepEqual(run.readPersistedSession(), newSession);
  assert.deepEqual(run.deviceSession.readSnapshot().localData, localData);
  assert.deepEqual(run.events.slice(-3), [
    "refresh:request",
    "signed-in",
    "refresh:error",
  ]);
});

test("Query 요청 함수의 동기 오류도 후속 조회 실패로 처리한다", async () => {
  const failure = new Error("요청 시작 실패");
  const run = setup({ requestSessionRefresh() { throw failure; } });
  assert.deepEqual(
    await run.signInAndRequestRefresh({}, { onSignedIn: run.onSignedIn }),
    newSession,
  );
  assert.deepEqual(run.refreshErrors, [failure]);
  assert.equal(run.events.at(-1), "signed-in");
});

test("서버 인증 실패는 기기 저장·조회·완료 알림으로 진행하지 않는다", async () => {
  const failure = new Error("서버 인증 실패");
  const run = setup({ requestAuthentication: async () => { throw failure; } });
  await assert.rejects(
    run.signInAndRequestRefresh({}, { onSignedIn: run.onSignedIn }),
    (error) => error === failure,
  );
  assert.deepEqual(run.events, ["authenticate"]);
  assert.deepEqual(run.deviceSession.readSnapshot().session, oldSession);
});

test("다른 계정과 귀속 불명 데이터는 삭제하거나 덮어쓰지 않는다", async () => {
  for (const accountId of ["another-user", null]) {
    const data = { accountId, trips: ["보존할 여행"] };
    let writes = 0;
    const store = createDeviceSessionStore({
      localData: data,
      persistSession: async () => { writes += 1; },
    });
    await assert.rejects(store.applyAuthentication(newSession), SessionOwnershipError);
    assert.equal(writes, 0);
    assert.deepEqual(store.readSnapshot(), {
      status: "signed-out",
      session: null,
      localData: data,
    });
  }
});

test("Login과 Reauth 소비자는 인증 완료를 안내하고 각자 이동·닫기를 요청한다", async () => {
  const cases = [
    { create: createLoginConsumer, action: "navigateToTrips", message: "로그인 완료" },
    { create: createReauthConsumer, action: "closeDialog", message: "인증을 복구했어요" },
  ];

  for (const consumer of cases) {
    const query = deferred();
    const run = setup({ requestSessionRefresh: () => query.promise });
    const messages = [];
    let actionCalls = 0;
    const submit = consumer.create({
      signInAndRequestRefresh: run.signInAndRequestRefresh,
      showMessage: (message) => messages.push(message),
      [consumer.action]: () => { actionCalls += 1; },
    });

    await submit({});
    assert.deepEqual(messages, [consumer.message]);
    assert.equal(actionCalls, 1);
    assert.deepEqual(run.deviceSession.readSnapshot().session, newSession);
    query.resolve();
  }
});

# 작업 시작 입력 — 인증 흐름의 이름과 완료 경계

> 이 문서는 이번 프로토타입에 부여한 초기 문제와 코드 가정이다. 기존 Noline의 실제 과거 코드나 커밋을 복원한 것이 아니다. 아래 발췌는 비교 입력이고, 현재 실행 가능한 구현은 [데모 소스](noline-demo/src/authentication.mjs)에 있다. 작업 후 이름과 검토는 [Work 현재 상태](noline-demo/context/work/workspaces/login-completion-names/current/state.md)에 따로 남긴다. 이 시작 입력을 사후 결과로 덮어쓰지 않는다. 작업 후 Project 현황은 [현재 연결](noline-demo/context/project/current/authentication-flow.md)에 있다.

## 현재 책임과 사용처

| 단위 | 이 예시에서 맡는 일 |
| --- | --- |
| `loginService.signIn` | 전체 세션 변경 서비스를 거쳐 진행 중 작업을 조율하고 계정·DB·queue 확인, 기기 저장, `signed-in` 적용을 마친다. 실패하면 기존 계약에 맞게 전달한다. Query 갱신은 이 함수에 들어 있지 않다. |
| `loginAndRefresh` | 위 서비스를 기다린 뒤 Query 무효화를 시작하고 재조회를 기다리지 않은 채 `onCompleted`를 부른다. |
| `LoginScreen` | `onCompleted`에서 기존 화면으로 이동한다. `onRefreshError`에서 후속 조회 실패를 처리한다. |
| `ReauthDialog` | `onCompleted`에서 재인증 모달을 닫는다. `onRefreshError`에서 후속 조회 실패를 처리한다. |

두 사용처는 모두 내부 코드라고 가정한다. 그 외 공개 소비자·외부 호환 계약은 없다고 놓았다. 이는 이번 가상 작업의 관찰 입력이며 Project 가이드의 영구적인 명명 정책이 아니다. 두 화면은 각각의 정책에 따라 이동·닫기를 수행하며 wrapper는 화면 반영 완료를 관찰하지 않는다.

## 변경 전 코드 발췌

전체 앱을 재현하는 실행 파일이 아니라 완료 경계를 보여 주는 발췌다. `LoginInput`, `queryClient`, `loginService`와 화면별 오류 처리는 이미 존재한다고 가정한다. 두 callback은 정상 반환하고 다시 던지지 않는다고 놓았다.

```ts
type LoginCallbacks = {
  onCompleted: () => void;
  onRefreshError: (error: unknown) => void;
};

async function loginAndRefresh(
  input: LoginInput,
  callbacks: LoginCallbacks,
): Promise<void> {
  await loginService.signIn(input);

  void queryClient
    .invalidateQueries({ queryKey: ["session-data"] })
    .catch(callbacks.onRefreshError);

  callbacks.onCompleted();
}
```

이 발췌에서는 Query 실패가 해당 Promise의 rejection으로 전달된다고 가정한다. Promise에 `void`를 붙인 것 자체가 실패 처리인 것은 아니며 연결된 `catch`와 callback이 처리 책임을 갖는다. Query 라이브러리 설정·버전 전체의 동작을 확인한 코드는 아니다.

## 초기 사용처와 표현

```ts
// LoginScreen
loginAndRefresh(input, {
  onCompleted: () => {
    showStatus("로그인과 화면 갱신 완료");
    navigateAfterSignIn();
  },
  onRefreshError: showQueryRefreshError,
});

// ReauthDialog
loginAndRefresh(input, {
  onCompleted: () => closeDialog(),
  onRefreshError: showQueryRefreshError,
});
```

초기 인터페이스와 두 호출부에는 callback의 완료 범위를 설명하는 가까운 주석이 없다고 가정한다. LoginScreen에는 재조회·렌더까지 끝났다고 읽히는 표시 문구가 있다. `navigateAfterSignIn`은 기존 이동 정책을 실행하는 소비자 동작이고 `closeDialog`는 기존 닫기 동작이며, 여기서 새 화면 정책을 제안한 것이 아니다.

비교할 현재 약속은 [인증 계약](noline-demo/context/project/guidance/authentication-and-session.md), Project 자체의 표현 요구는 [가독성 가이드](noline-demo/context/project/guidance/code-readability.md)에서 읽는다. 이 초기 입력에는 개선 이름이나 개명 결론을 미리 적지 않는다. 이름을 유지하며 설명을 보완할지, 개명할지, 동작의 문제가 있는지는 Work에서 판단한다.

초기 가정과 현재 구현을 구별한다. 위 발췌는 변경 이유를 비교하는 입력이며, 지금의 함수·대기·실패 동작은 데모 소스와 테스트에서 확인한다. 초기판과의 실제 제품 회귀를 검증한 것은 아니다. 보존된 Noline 문서만으로 이 함수명·대기 동작을 도출한 것도 아니다.

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath, pathToFileURL} from 'node:url';

const viewerDirectory = path.dirname(fileURLToPath(import.meta.url));
const root = path.dirname(viewerDirectory);

async function loadMarked() {
  const configuredModule = process.env.MARKED_MODULE;
  if (configuredModule) {
    const moduleUrl = configuredModule.startsWith('file:')
      ? configuredModule
      : pathToFileURL(path.resolve(configuredModule)).href;
    return import(moduleUrl);
  }
  try { return await import('marked'); }
  catch (error) {
    throw new Error('설치된 marked를 찾지 못했습니다. MARKED_MODULE에 로컬 marked 모듈 파일 경로를 지정해 다시 실행하세요.', {cause: error});
  }
}

const {Marked} = await loadMarked();
const personalRoot = 'ai-workspace/context/personal/';
const personal = personalRoot + 'development/naming-and-completion.md';
const personalCommon = personalRoot + 'development/README.md';
const workflow = 'workflow/development.md';
const project = 'noline-demo/context/project/';
const work = 'noline-demo/context/work/workspaces/login-completion-names/';
const escapeHtml = text => text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
const slug = text => text.toLowerCase().replace(/[^\p{L}\p{N}_\s-]/gu, '').trim().replace(/\s+/g, '-');

function sourceFiles(directory) {
  return fs.readdirSync(directory, {withFileTypes: true}).flatMap(entry => {
    const fullPath = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      return fullPath === viewerDirectory ? [] : sourceFiles(fullPath);
    }
    if (!entry.isFile()) { return []; }
    const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
    const isDocument = entry.name.endsWith('.md');
    const isDemoCode = /^noline-demo\/(?:src|tests)\/.+\.mjs$/.test(relativePath);
    return isDocument || isDemoCode ? [fullPath] : [];
  });
}

function renderMarkdown(content) {
  const headingCounts = new Map();
  const renderer = {
    html({text}) { return escapeHtml(text); },
    heading({tokens, depth, text}) {
      const base = slug(text);
      const count = headingCounts.get(base) || 0;
      headingCounts.set(base, count + 1);
      const id = count ? `${base}-${count}` : base;
      return `<h${depth} id="${escapeHtml(id)}">${this.parser.parseInline(tokens)}</h${depth}>\n`;
    },
    image({text, href}) {
      return `<span title="${escapeHtml(href)}">${escapeHtml(text || '이미지 참조')}</span>`;
    },
  };
  return new Marked({renderer, gfm: true, breaks: false}).parse(content);
}

const labels = {
